import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage>
    with WidgetsBindingObserver, SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  List<CurrencyModel> _allCurrencies = [];

  int _page = 0;
  bool _hasMore = true;
  bool _isLoading = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _loadData(page: 0, isInitialLoad: true);
  }

  @override
  void didChangeLifecycle(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && !_isLoading) {
      // При возвращении на экран — перезагрузка с USD и сброс пагинации
      _loadData(page: 0, isInitialLoad: true);
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadData({required int page, required bool isInitialLoad}) async {
    final currencyRepository = context.read<CurrencyRepository>();

    if (isInitialLoad) {
      setState(() {
        _allCurrencies = [];
        _page = 0;
        _hasMore = true;
        _isLoading = true;
      });
    }

    final request = CurrencyPageRequest(
      base: 'USD',
      page: page,
      pageSize: 20,
    );

    try {
      final result = await currencyRepository.fetchRates(request);

      if (!mounted) return;

      setState(() {
        if (isInitialLoad || page == 0) {
          _allCurrencies = List.from(result.items);
        } else {
          // Дописываем новые элементы к существующему списку
          final currentLength = _allCurrencies.length;
          for (final item in result.items) {
            _allCurrencies.add(item);
          }
          // Обновляем только добавленные элементы для фильтрации
          if (_filteredCurrenciesNotifier.value.length < _allCurrencies.length) {
            final newFiltered = List<CurrencyModel>.from(_allCurrencies);
            _filteredCurrenciesNotifier.value = newFiltered;
          } else {
            _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
          }
        }

        if (isInitialLoad) {
          _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
        }

        _page = page;
        _hasMore = result.hasMore;
        _isLoading = false;

        if (_fadeController.isAnimating == false && _fadeController.isCompleted == false) {
          _fadeController.forward();
        }
      });

      currencyRepository.saveCurrencyList(_allCurrencies);
    } catch (_) {
      if (mounted) {
        setState(() {
          _isLoading = false;
        });
      }
    }
  }

  Future<void> _loadMore() async {
    final nextPage = _page + 1;
    await _loadData(page: nextPage, isInitialLoad: false);
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) ||
          currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: ValueListenableBuilder<List<CurrencyModel>>(
        valueListenable: _filteredCurrenciesNotifier,
        builder: (BuildContext context, List<CurrencyModel> data, _) {
          if (_isLoading && data.isEmpty) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ListView.builder(
                    itemCount: data.length + (_hasMore && !_isLoading ? 1 : 0),
                    itemBuilder: (BuildContext context, int index) {
                      // Показываем кнопку "Показать ещё" в конце списка
                      if (index == data.length && _hasMore && !_isLoading) {
                        return Padding(
                          padding: const EdgeInsets.only(top: 20, bottom: 30),
                          child: Center(
                            child: ElevatedButton(
                              onPressed: _loadMore,
                              child: Text(context.loc.showMore),
                            ),
                          ),
                        );
                      }

                      final CurrencyModel currency = data[index];

                      return Padding(
                        key: ValueKey(currency.id),
                        padding: index == 0
                            ? const EdgeInsets.only(top: 20)
                            : const EdgeInsets.only(top: 10),
                        child: CurrencyCard(model: currency),
                      );
                    },
                    padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
