          }

          // Обновляем отображаемый список с учётом текущего фильтра
          _filteredCurrenciesNotifier.value = _applyFilter(_searchQuery);
        }

        if (isInitialLoad) {
          _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
        }

        _page = page;
        _hasMore = result.hasMore;
        _isLoading = false;

        if (_fadeController.isAnimating == false && _fadeController.isCompleted == false) {
          _fadeController.forward();
        }
      });

      currencyRepository.saveCurrencyList(_allCurrencies);
    } catch (_) {
      if (mounted) {
        setState(() {
          _isLoading = false;
        });
      }
    }
  }

  List<CurrencyModel> _applyFilter(String query) {
    final String lowerQuery = query.toLowerCase();
    return _allCurrencies
        .where((CurrencyModel currency) {
          return currency.name.toLowerCase().contains(lowerQuery) ||
              currency.symbol.toLowerCase().contains(lowerQuery);
        })
        .toList(growable: false);
  }

  Future<void> _loadMore() async {
    final nextPage = _page + 1;
    await _loadData(page: nextPage, isInitialLoad: false);
  }

  void _filterCurrencies(String query) {
    _searchQuery = query;
    _filteredCurrenciesNotifier.value = _applyFilter(query);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: ValueListenableBuilder<List<CurrencyModel>>(
        valueListenable: _filteredCurrenciesNotifier,
        builder: (BuildContext context, List<CurrencyModel> data, _) {
          if (_isLoading && data.isEmpty) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ListView.builder(
                    itemCount: data.length + (_hasMore && !_isLoading ? 1 : 0),
                    itemBuilder: (BuildContext context, int index) {
                      // Показываем кнопку "Показать ещё" в конце списка
                      if (index == data.length && _hasMore && !_isLoading) {
                        return Padding(
                          padding: const EdgeInsets.only(top: 20, bottom: 30),
                          child: Center(
                            child: ElevatedButton(
                              onPressed: _loadMore,
                              child: Text(context.loc.showMore),
                            ),
                          ),
                        );
                      }

                      final CurrencyModel currency = data[index];

                      return Padding(
                        key: ValueKey(currency.id),
                        padding: index == 0
                            ? const EdgeInsets.only(top: 20)
                            : const EdgeInsets.only(top: 10),
                        child: CurrencyCard(model: currency),
                      );
                    },
                    padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
